  case NamingConflictType.ReplaceExisitingLocalSubstrate:
    S4PRESS.SelectRadioButton(S4General.UIMap.Temporary.replaceLocalSubstrate); break;
  case NamingConflictType.RenameLocalSubstrate:
    S4PRESS.SelectRadioButton(S4General.UIMap.Temporary.changeLocalSubstrateName); break;
}

