while (!float.TryParse(S4PRESS.WaitForUserInput("To Do", "Measure ...").getValue(), out GripperBiteMeasure))
{
    S4PRESS.WaitForUserAction("Notice", "The input entered is not valid...");
}

if (GripperBiteMeasure < 3.5)
{
    Common.WarningTest("Gripper Bite on the leading edge is smaller than 3.5 mm - Fix Issue");
}

int WaterPressure = S4PRESS.ExtendedLookupAndGetValue("ActivationID:UtilityCabinet.ChillerAndWater.CwsDataEnum_CWS_PRESSURE", "LevelDisplayControl", "isUserVisible:True+Property:CurrentValue", "ActiveWindow").ValueToInt();
if (WaterPressure < 5000 || WaterPressure > 6500)
    S4PRESS.WaitForUserAction("Water Pressure", $"Current value {WaterPressure} not in range 5000-6500 mb");

int WaterFlow = S4PRESS.ExtendedLookupAndGetValue("ActivationID:UtilityCabinet.ChillerAndWater.CwsDataEnum_CWS_FLOW", "LevelDisplayControl", "isUserVisible:True+Property:CurrentValue", "ActiveWindow").ValueToInt();
if (WaterFlow < 50)
    S4PRESS.WaitForUserAction("Water Flow", $"Current value {WaterFlow} below min 50 lit/min");

S4PRESS.extendedLookupAndClick("ActivationID:UtilityCabinet.ImoBarak.ImagingOilElements_HX_HIGH_VALVE", "ToggleButton", "isUserVisible:True+index:0", "ActiveWindow");
S4PRESS.WaitForUserAction("ImO Valves HIGH valve", "Verify by hearing and a screwdriver that the valve is open");
S4PRESS.extendedLookupAndClick("ActivationID:UtilityCabinet.ImoBarak.ImagingOilElements_HX_HIGH_VALVE", "ToggleButton", "isUserVisible:True+index:1", "ActiveWindow");

