    Common.WriteLog($"icon {item.Key} appeared");
else
    Common.FailTest($"icon {item.Key} didn't appear");

foreach (var item in sensorsID) {
    S4PRESS.SetSysTabValue(topic, "0", sensorID, "0", "Dynamic", item.Value);
    S4PRESS.SetSysTabValue(topic, "0", sensorState, "0", "Dynamic", "1");
